{
  "items": [
    {
      "concept_name": {
        "text": "Spam classification using pattern recognition",
        "refs": ["Q0000", "Q0001", "Q0004"],
        "claims": [
          {
            "text": "Google classifies emails as spam or non-spam by looking for patterns such as limited offers or suspicious sender IDs.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0000", "Q0001", "Q0004"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Human-based spam detection involves training a person on thousands of spam and non‑spam emails to recognize patterns.",
        "refs": ["Q0002", "Q0003", "Q0005", "Q0006"],
        "claims": [
          {
            "text": "A human can be trained on 10,000 spam and 10,000 non‑spam emails to learn patterns for classification.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0002", "Q0003", "Q0005", "Q0006"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Machine learning training phase",
        "refs": ["Q0006", "Q0010"],
        "claims": [
          {
            "text": "In machine learning, the first phase is training where a computer program is given many examples of spam and non‑spam emails.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0006", "Q0010"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "During training, the model learns patterns from the data.",
        "refs": ["Q0006", "Q0010"],
        "claims": [
          {
            "text": "Training allows the computer program to detect patterns in email data.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0006", "Q0010"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Machine learning inference phase",
        "refs": ["Q0010"],
        "claims": [
          {
            "text": "The second phase, inference, is when the trained model receives new emails and predicts whether they are spam.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0010"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "Inference uses the patterns learned during training to make predictions on unseen inputs.",
        "refs": ["Q0010"],
        "claims": [
          {
            "text": "During inference the model applies learned patterns to classify new emails.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0010"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Analogy of pattern extraction to squares",
        "refs": ["Q0008", "Q0011"],
        "claims": [
          {
            "text": "Just as one can recognize that 1²=1, 2²=4, 3²=9, a computer can extract patterns from data.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "alternative_valid_approach",
            "refs": ["Q0008", "Q0011"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "The speaker uses the square numbers example to illustrate how patterns are learned.",
        "refs": ["Q0008", "Q0011"],
        "claims": [
          {
            "text": "Recognizing the pattern of squares demonstrates how a model learns relationships between inputs and outputs.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "explanation_of_mistake",
            "refs": ["Q0008", "Q0011"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    },
    {
      "concept_name": {
        "text": "Difference between traditional software and machine learning",
        "refs": ["Q0011"],
        "claims": [
          {
            "text": "Traditional software uses explicit equations (e.g., y = x²) coded by the programmer, whereas machine learning learns a function from data.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "prerequisite",
            "refs": ["Q0011"],
            "related_refs": []
          }
        ]
      },
      "content": {
        "text": "In traditional programming you write the logic; in ML you provide input‑output pairs and let the model infer the logic.",
        "refs": ["Q0011"],
        "claims": [
          {
            "text": "Machine learning replaces hand‑written logic with learned patterns from data.",
            "basis": "explicit",
            "availability": "SOURCE_SUPPORTED",
            "literal_kind": "verbal",
            "instructional_role": "correct_demonstration",
            "refs": ["Q0011"],
            "related_refs": []
          }
        ]
      },
      "aliases": null
    }
  ],
